package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.JSON;
import com.alibaba.fastjson2.JSONArray;
import com.alibaba.fastjson2.JSONObject;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.paiflow.domain.DataRecord;
import com.ruoyi.paiflow.mapper.DataMapper;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

/** 原数据库管理闭环；所有表列和值先核验，Mapper只访问固定中心表。 */
@Service
@ConditionalOnProperty(prefix="paiflow",name="enabled",havingValue="true")
@Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
public class DataResourceService {
    public static final String QUERY="paiflow:data:query",EDIT="paiflow:data:edit";
    public static final int MAX_ROWS=10000;
    private static final Set<String> SYSTEM=Set.of("id","uid","create_time"),TYPES=Set.of("String","Integer","Time","Number","Boolean");
    private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
    private final DataMapper mapper;private final DefaultPersonalSpaceService personal;private final ResourceAccessService access;
    public DataResourceService(DataMapper mapper,DefaultPersonalSpaceService personal,ResourceAccessService access){this.mapper=mapper;this.personal=personal;this.access=access;}
    public DefaultPersonalSpaceService.Selection selection(String header,Object echo,boolean edit){return personal.select(header,echo,edit?EDIT:QUERY);}
    private Long space(DefaultPersonalSpaceService.Selection scope,boolean edit){var id=personal.existing(scope,edit?EDIT:QUERY);if(id!=null)access.requireSpace(id,edit?EDIT:QUERY,edit?2:3,edit);return id;}
    public DataRecord database(DefaultPersonalSpaceService.Selection scope,long id,boolean edit){var selected=space(scope,edit);var value=edit?mapper.lockDatabase(id):mapper.database(id);if(selected==null || value==null || value.getDeleted()!=0 || !Objects.equals(selected,value.getSpaceId()))throw fail("数据库资源不存在或不可访问",404);return value;}
    public DataRecord table(DefaultPersonalSpaceService.Selection scope,long id,boolean edit){var value=mapper.table(id);if(value==null || value.getDeleted()!=0)throw fail("表不存在或不可访问",404);database(scope,value.getDbId(),edit);if(edit)value=mapper.lockTable(id);if(value==null || value.getDeleted()!=0)throw fail("表已删除",404);return value;}
    public JSONObject detail(DefaultPersonalSpaceService.Selection scope,long id){return databaseView(database(scope,id,false));}
    private JSONObject databaseView(DataRecord r){var actual=access.requireSpace(r.getSpaceId(),QUERY,3,false);return JSONObject.of("id",r.getId(),"dbId",r.getId(),"uid",IdentityMappingService.legacyUid(r.getOwnerUserId()),"spaceId",DefaultPersonalSpaceService.legacySpaceId(actual),"appId",null,"name",r.getName(),"description",r.getDescription(),"avatarIcon",r.getAvatarIcon(),"avatarColor",r.getAvatarColor(),"deleted",false,"revision",r.getRevision(),"createTime",r.getCreateTime(),"updateTime",r.getUpdateTime());}
    public JSONObject list(DefaultPersonalSpaceService.Selection scope,JSONObject body){var selected=space(scope,false);var values=new ArrayList<JSONObject>();String search=optional(body.get("search"),128);if(selected!=null){var rows=mapper.databases(selected);if(rows.size()>MAX_ROWS)throw fail("数据库目录超过读取预算",413);for(var r:rows)if(search.isEmpty() || r.getName().contains(search))values.add(databaseView(r));}return page(values,body);}
    public long create(DefaultPersonalSpaceService.Selection scope,JSONObject body){String name=text(body.get("name"),128,"库名称");long id=personal.materialize(scope,EDIT);access.requireSpace(id,EDIT,2,true);uniqueDb(id,name,null);var row=new DataRecord();row.setSpaceId(id);row.setOwnerUserId(scope.ownerUserId());row.setName(name);row.setDescription(optional(body.get("description"),2000));row.setAvatarIcon(optional(body.get("avatarIcon"),1024));row.setAvatarColor(optional(body.get("avatarColor"),128));row.setDeleted(0);row.setRevision(0L);if(mapper.insertDatabase(row)!=1)throw fail("库保存失败",500);return row.getId();}
    public void update(DefaultPersonalSpaceService.Selection scope,JSONObject body){var row=database(scope,id(body.get("id")),true);checkRevision(row,body);if(body.containsKey("name")){var name=text(body.get("name"),128,"库名称");uniqueDb(row.getSpaceId(),name,row.getId());row.setName(name);}if(body.containsKey("description"))row.setDescription(optional(body.get("description"),2000));if(body.containsKey("avatarIcon"))row.setAvatarIcon(optional(body.get("avatarIcon"),1024));if(body.containsKey("avatarColor"))row.setAvatarColor(optional(body.get("avatarColor"),128));saveDb(row);}
    public void delete(DefaultPersonalSpaceService.Selection scope,long id){var row=database(scope,id,true);if(mapper.referencedDatabase(id)>0)throw fail("数据库已被固定工作流版本引用",409);for(var t:mapper.tables(id)){t=mapper.lockTable(t.getId());t.setDeleted(1);saveTable(t);}row.setDeleted(1);saveDb(row);}
    public long copy(DefaultPersonalSpaceService.Selection scope,long id,String name){var source=database(scope,id,true);String chosen=name==null||name.isBlank()?source.getName()+"_副本":name;long target=create(scope,JSONObject.of("name",chosen,"description",source.getDescription(),"avatarIcon",source.getAvatarIcon(),"avatarColor",source.getAvatarColor()));for(var t:mapper.tables(id))copyTableInside(t,target,t.getName());return target;}
    private void uniqueDb(long space,String name,Long except){for(var r:mapper.databases(space))if(name.equals(r.getName())&&!Objects.equals(except,r.getId()))throw fail("库名称已存在",409);}
    public List<JSONObject> tables(DefaultPersonalSpaceService.Selection scope,long db){database(scope,db,false);var result=new ArrayList<JSONObject>();for(var t:mapper.tables(db))result.add(tableView(t));return result;}
    public List<JSONObject> tree(DefaultPersonalSpaceService.Selection scope){var selected=space(scope,false);var result=new ArrayList<JSONObject>();if(selected!=null)for(var db:mapper.databases(selected)){var children=new JSONArray();for(var table:mapper.tables(db.getId()))children.add(JSONObject.of("value",table.getName(),"label",table.getName(),"children",new JSONArray(),"id",table.getId()));result.add(JSONObject.of("value",String.valueOf(db.getId()),"label",db.getName(),"children",children));}return result;}
    private static JSONObject tableView(DataRecord t){return JSONObject.of("id",t.getId(),"dbId",t.getDbId(),"name",t.getName(),"description",t.getDescription(),"deleted",false,"revision",t.getRevision(),"createTime",t.getCreateTime(),"updateTime",t.getUpdateTime());}
    public long createTable(DefaultPersonalSpaceService.Selection scope,JSONObject body){var db=database(scope,id(body.get("dbId")),true);String name=identifier(body.get("name"));uniqueTable(db.getId(),name,null);if(mapper.tables(db.getId()).size()>=20)throw fail("一个库最多20张表",413);var fields=validatedFields(body.getJSONArray("fields"),null);var t=new DataRecord();t.setDbId(db.getId());t.setName(name);t.setDescription(optional(body.get("description"),2000));t.setFieldsJson(RunJsonBoundary.canonicalFull(fields));t.setDeleted(0);t.setRevision(0L);if(mapper.insertTable(t)!=1)throw fail("表保存失败",500);saveDb(db);return t.getId();}
    public JSONObject fields(DefaultPersonalSpaceService.Selection scope,JSONObject body){var t=table(scope,id(body.get("tbId")),false);var list=new ArrayList<JSONObject>();for(Object item:JSON.parseArray(t.getFieldsJson())){var f=JSON.parseObject(item.toString());f.put("tbId",t.getId());f.put("createTime",t.getCreateTime());f.put("updateTime",t.getUpdateTime());list.add(f);}return page(list,body);}
    public void updateTable(DefaultPersonalSpaceService.Selection scope,JSONObject body){var t=table(scope,id(body.get("id")),true);checkRevision(t,body);var db=mapper.lockDatabase(t.getDbId());if(body.containsKey("name")){String name=identifier(body.get("name"));uniqueTable(t.getDbId(),name,t.getId());t.setName(name);}if(body.containsKey("description"))t.setDescription(optional(body.get("description"),2000));if(body.containsKey("fields")){var old=JSON.parseArray(t.getFieldsJson());var changed=validatedFields(body.getJSONArray("fields"),old);for(int env:List.of(1,2))for(var data:loadRows(t.getId(),env)){var values=new JSONObject();for(Object item:changed){var f=(JSONObject)item;String n=f.getString("name");var prior=old.stream().filter(x->Objects.equals(((JSONObject)x).get("id"),f.get("id"))).map(x->(JSONObject)x).findFirst().orElse(null);Object v=prior==null?defaultValue(f,true):data.get(prior.getString("name"));values.put(n,convert(v,f));}if(mapper.updateRow(t.getId(),env,id(data.get("id")),RunJsonBoundary.canonicalFull(values))!=1)throw fail("表行迁移发生冲突",409);}t.setFieldsJson(RunJsonBoundary.canonicalFull(changed));}saveTable(t);saveDb(db);}
    public void deleteTable(DefaultPersonalSpaceService.Selection scope,long id){var t=table(scope,id,true);if(mapper.referencedTable(id)>0)throw fail("表已被固定工作流版本引用",409);t.setDeleted(1);saveTable(t);saveDb(mapper.lockDatabase(t.getDbId()));}
    public long copyTable(DefaultPersonalSpaceService.Selection scope,long id){var source=table(scope,id,true);String name=source.getName()+"_copy";identifier(name);uniqueTable(source.getDbId(),name,null);long target=copyTableInside(source,source.getDbId(),name);saveDb(mapper.lockDatabase(source.getDbId()));return target;}
    private long copyTableInside(DataRecord source,long db,String name){if(mapper.tables(db).size()>=20)throw fail("一个库最多20张表",413);var t=new DataRecord();t.setDbId(db);t.setName(name);t.setDescription(source.getDescription());t.setFieldsJson(source.getFieldsJson());t.setDeleted(0);t.setRevision(0L);if(mapper.insertTable(t)!=1)throw fail("复制表保存失败",500);for(int env:List.of(1,2))for(var row:loadRows(source.getId(),env)){var record=new HashMap<String,Object>();record.put("table",t.getId());record.put("env",env);record.put("json",RunJsonBoundary.canonicalFull(row));if(mapper.insertRow(record)!=1)throw fail("复制数据保存失败",500);row.put("id",record.get("id"));if(mapper.updateRow(t.getId(),env,id(record.get("id")),RunJsonBoundary.canonicalFull(row))!=1)throw fail("复制数据标识保存失败",500);}return t.getId();}
    private void uniqueTable(long db,String name,Long except){for(var t:mapper.tables(db))if(name.equals(t.getName())&&!Objects.equals(except,t.getId()))throw fail("表名称已存在",409);}
    private void saveDb(DataRecord row){if(mapper.updateDatabase(row)!=1)throw fail("库版本已变化",409);row.setRevision(row.getRevision()+1);}
    private void saveTable(DataRecord row){if(mapper.updateTable(row)!=1)throw fail("表版本已变化",409);row.setRevision(row.getRevision()+1);}
    private static void checkRevision(DataRecord row,JSONObject body){if(body.get("revision")!=null && idOrZero(body.get("revision"))!=row.getRevision())throw fail("资源版本已变化",409);}
    public JSONObject data(DefaultPersonalSpaceService.Selection scope,JSONObject body){var t=table(scope,id(body.get("tbId")),false);return page(loadRows(t.getId(),environment(body.get("execDev"))),body);}
    public void operate(DefaultPersonalSpaceService.Selection scope,JSONObject body){var t=table(scope,id(body.get("tbId")),true);int env=environment(body.get("execDev"));var changes=body.getJSONArray("data");if(changes==null || changes.isEmpty() || changes.size()>1000)throw fail("行操作须为1至1000项",400);for(Object raw:changes){if(!(raw instanceof JSONObject change))throw fail("行操作格式无效",400);int op=(int)id(change.get("operateType"));var value=change.getJSONObject("tableData");if(value==null)throw fail("缺少行正文",400);mutateRow(t,env,op,value,scope.ownerUserId());}}
    public JSONObject insert(DataRecord t,int env,JSONObject values,long owner){return mutateRow(t,env,1,values,owner);}
    public JSONObject mutateRow(DataRecord t,int env,int op,JSONObject input,long owner){var fields=JSON.parseArray(t.getFieldsJson());Set<String> names=new HashSet<>();for(Object f:fields)names.add(((JSONObject)f).getString("name"));if(!names.containsAll(input.keySet()))throw fail("行含未声明列",400);if(op==4){long id=id(input.get("id"));if(mapper.deleteRow(t.getId(),env,id)!=1)throw fail("待删除行不存在",404);return JSONObject.of("id",id);}var values=new JSONObject();if(op==2){long id=id(input.get("id"));var old=loadRows(t.getId(),env).stream().filter(v->id(v.get("id"))==id).findFirst().orElseThrow(()->fail("待编辑行不存在",404));values.putAll(old);}else if(op!=1)throw fail("未知行操作",400);for(Object item:fields){var f=(JSONObject)item;String name=f.getString("name");if(SYSTEM.contains(name)){if(op==1 && input.containsKey(name))throw fail("系统列由中心填写",400);if(op==2&&input.containsKey(name)&&!Objects.equals(input.get(name),values.get(name)))throw fail("系统列不能修改",400);continue;}if(input.containsKey(name))values.put(name,convert(input.get(name),f));else if(op==1)values.put(name,defaultValue(f,false));}RunJsonBoundary.check(values,RunProtocolLimits.INPUT_BYTES);if(op==1){if(mapper.countRows(t.getId(),env)>=MAX_ROWS)throw fail("逻辑表超过10000行处理预算",413);values.put("uid",IdentityMappingService.legacyUid(owner));values.put("create_time",TIME.format(LocalDateTime.now(ZoneOffset.UTC)));var record=new HashMap<String,Object>();record.put("table",t.getId());record.put("env",env);record.put("json",RunJsonBoundary.canonicalFull(values));if(mapper.insertRow(record)!=1)throw fail("行保存失败",500);values.put("id",record.get("id"));}if(mapper.updateRow(t.getId(),env,id(values.get("id")),RunJsonBoundary.canonicalFull(values))!=1)throw fail("行保存发生冲突",409);return values;}
    public List<JSONObject> loadRows(long table,int env){var result=new ArrayList<JSONObject>();var rows=mapper.rows(table,env,MAX_ROWS+1);if(rows.size()>MAX_ROWS)throw fail("逻辑表超过10000行处理预算",413);for(var row:rows){var value=JSON.parseObject((String)row.get("rowJson"));value.put("id",row.get("id"));result.add(value);}return result;}
    private static JSONArray validatedFields(JSONArray input,JSONArray old){if(input==null)throw fail("缺少字段列表",400);var byId=new LinkedHashMap<Long,JSONObject>();long next=4;if(old==null){byId.put(1L,system(1,"id","Integer"));byId.put(2L,system(2,"uid","String"));byId.put(3L,system(3,"create_time","Time"));}else for(Object item:old){var f=(JSONObject)item;long id=id(f.get("id"));byId.put(id,f);next=Math.max(next,id+1);}for(Object raw:input){if(!(raw instanceof JSONObject item))throw fail("字段格式无效",400);String name=identifier(item.get("name"));if(SYSTEM.contains(name)){if(old!=null && item.get("id")!=null){var existing=byId.get(id(item.get("id")));if(existing==null || !name.equals(existing.get("name")))throw fail("系统字段标识不一致",400);}continue;}int operation=item.getIntValue("operateType");Long original=item.get("id")==null?null:idOrZero(item.get("id"));if(old!=null && operation==4){if(original==null||byId.remove(original)==null)throw fail("待删除字段不存在",404);continue;}if(old!=null && operation!=1){if(original==null || !byId.containsKey(original) || byId.get(original).getBooleanValue("isSystem"))throw fail("待编辑字段不属于此表",400);}else original=next++;String type=text(item.get("type"),16,"字段类型");if(!TYPES.contains(type))throw fail("字段类型无效",400);var f=JSONObject.of("id",original,"name",name,"type",type,"description",optional(item.get("description"),2000),"defaultValue",item.get("defaultValue"),"isRequired",item.getBooleanValue("isRequired"),"isSystem",false);if(f.get("defaultValue")!=null && !"".equals(f.get("defaultValue")))convert(f.get("defaultValue"),f);byId.put(original,f);}if(byId.size()>20 || byId.size()<4)throw fail("表须有1至17个自定义字段",400);Set<String> names=new HashSet<>();for(var f:byId.values())if(!names.add(f.getString("name")))throw fail("字段名称重复",409);return new JSONArray(byId.values());}
    private static JSONObject system(long id,String name,String type){return JSONObject.of("id",id,"name",name,"type",type,"description","系统列","defaultValue",null,"isRequired",true,"isSystem",true);}
    public static Object defaultValue(JSONObject field,boolean excel){Object value=field.get("defaultValue");if(value!=null && !"".equals(value))return convert(value,field);if(!field.getBooleanValue("isRequired"))return "String".equals(field.get("type"))?"":null;if(!excel)throw fail("缺少必填字段："+field.getString("name"),400);return switch(field.getString("type")){case "Integer"->0L;case "Number"->BigDecimal.ZERO;case "Boolean"->false;case "Time"->TIME.format(LocalDateTime.now(ZoneOffset.UTC));default->"";};}
    public static Object convert(Object value,JSONObject field){if(value==null){if(field.getBooleanValue("isRequired"))throw fail("必填列不能为空："+field.getString("name"),400);return null;}String type=field.getString("type");try{return switch(type){case "Integer"->new BigDecimal(String.valueOf(value)).longValueExact();case "Number"->{var n=new BigDecimal(String.valueOf(value));if(n.precision()>100 || Math.abs((long)n.scale())>100)throw new IllegalArgumentException();yield n;}case "Boolean"->{if(value instanceof Boolean)yield value;if("true".equalsIgnoreCase(String.valueOf(value)))yield true;if("false".equalsIgnoreCase(String.valueOf(value)))yield false;throw new IllegalArgumentException();}case "Time"->TIME.format(LocalDateTime.parse(String.valueOf(value),TIME));case "String"->{if(!(value instanceof String s) || s.length()>65535)throw new IllegalArgumentException();yield s;}default->throw new IllegalArgumentException();};}catch(RuntimeException error){throw fail("字段类型或默认值无效："+field.getString("name"),400);}}
    public static JSONObject page(List<?> list,JSONObject body){long current=body.get("pageNum")==null?1:id(body.get("pageNum")),size=body.get("pageSize")==null?20:id(body.get("pageSize"));if(size>1000)throw fail("分页大小超过1000",400);long start=(current-1)*size;if(start<0)throw fail("分页越界",400);var rows=start>=list.size()?List.of():list.subList((int)start,(int)Math.min(start+size,list.size()));return JSONObject.of("records",rows,"total",list.size(),"size",size,"current",current,"pages",(list.size()+size-1)/size);}
    public static int environment(Object raw){long value=id(raw);if(value!=1 && value!=2)throw fail("数据环境须为测试1或正式2",400);return(int)value;}
    public static String identifier(Object raw){String name=text(raw,63,"表/列标识符");if(!name.matches("[A-Za-z_][A-Za-z0-9_]*"))throw fail("表列只能使用英文字母、数字和下划线",400);return name;}
    public static long id(Object raw){long value=idOrZero(raw);if(value<1)throw fail("标识符须为正整数",400);return value;}
    public static long idOrZero(Object raw){try{if(!(raw instanceof Number || raw instanceof String)||!String.valueOf(raw).matches("[0-9]{1,19}"))throw new IllegalArgumentException();return Long.parseLong(String.valueOf(raw));}catch(RuntimeException e){throw fail("整数标识符无效",400);}}
    public static String optional(Object raw,int max){if(raw==null)return "";if(!(raw instanceof String value)||value.length()>max||value.indexOf('\0')>=0)throw fail("文本格式或长度无效",400);return value;}
    public static String text(Object raw,int max,String label){String value=optional(raw,max);if(value.isBlank())throw fail(label+"不能为空",400);return value;}
    public static ServiceException fail(String message,int code){return new ServiceException(message,code);}
}
